/**
 * Fixed word lists used by the noise-removal rules (Req 3.2, 3.5, 3.7).
 * Everything here is in folded form and deep-frozen.
 */
function freezeSequences(sequences) {
    return Object.freeze(sequences.map((tokens) => Object.freeze([...tokens])));
}
/**
 * Card, POS and debit prefixes (Req 3.2) as folded token sequences.
 * Sorted longest first (token count, then character count) so the first
 * match found is the longest. `sepa-lastschrift` is one token because the
 * lexer keeps `-` inside a word.
 */
export const CARD_PREFIXES = freezeSequences([
    ["debit", "card", "purchase"],
    ["sepa", "direct", "debit"],
    ["recurring", "payment"],
    ["sepa", "lastschrift"],
    ["recurring", "debit"],
    ["card", "purchase"],
    ["visa", "purchase"],
    ["direct", "debit"],
    ["pos", "purchase"],
    ["check", "card"],
    ["debit", "card"],
    ["visa", "debit"],
    ["ach", "debit"],
    ["pos", "debit"],
    ["sepa-lastschrift"],
    ["kartenzahlung"],
    ["contactless"],
    ["lastschrift"],
    ["prelevement"],
    ["mastercard"],
    ["checkcard"],
    ["recurring"],
    ["purchase"],
    ["debit"],
    ["visa"],
    ["ach"],
    ["pos"],
    ["dd"],
]);
